const uuid = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (char) => {
  const value = Math.floor(Math.random() * 16);
  return (char === 'x' ? value : ((value & 0x3) | 0x8)).toString(16);
});
return [{ json: { usage_event_id: `cp_usage_${uuid}` } }];

const response = $input.first().json || {};
const context = $('Set Prototype Metadata').first().json || {};
const usage = response.usage || {};
const startedAt = Date.parse(context.started_at || '');
const latencyMs = Number.isFinite(startedAt) ? Date.now() - startedAt : null;
const promptTokens = Number(usage.prompt_tokens ?? 0);
const completionTokens = Number(usage.completion_tokens ?? 0);
const totalTokens = Number(usage.total_tokens ?? promptTokens + completionTokens);
const explicitCost = Number(response._hidden_params?.response_cost ?? response.usage?.cost ?? response.cost ?? Number.NaN);
const fallbackCost = ((promptTokens * 0.55) + (completionTokens * 1.1)) / 1000000;
const estimatedCost = Number.isFinite(explicitCost) ? explicitCost : fallbackCost;

return [{
  json: {
    usage_event_id: context.usage_event_id,
    account_slug: context.account_slug,
    provider: 'deepseek',
    service_name: 'litellm-chat-completions',
    model_name: 'deepseek-chat',
    input_tokens: promptTokens,
    output_tokens: completionTokens,
    total_tokens: totalTokens,
    estimated_cost: Number.isFinite(estimatedCost) ? estimatedCost : 0,
    latency_ms: latencyMs,
    usage_at: new Date().toISOString(),
    workflow: context.workflow,
    workflow_id: context.workflow_id,
    n8n_execution_id: context.n8n_execution_id,
    node: context.node,
    environment: context.environment,
    business_action: context.business_action,
    litellm_request_id: response.id ?? null,
    tags: JSON.parse(context.tags_json || '[]'),
    completion_result: response.choices?.[0]?.message?.content ?? null,
  },
}];

const result = $input.first().json || {};
return [{
  json: {
    status: result.status,
    usage_event_id: result.usage_event_id,
    usage_record_id: result.usage_record_id,
    provider_connection_id: result.provider_connection_id,
    provider: result.provider,
    total_tokens: result.total_tokens,
    calculated_cost: result.calculated_cost,
  },
}];
